L["Sync cleared -- fewer than two specs remained selected."] = "Sincronização limpa -- restaram menos de duas especializações selecionadas."
L["Sync cleared -- only one spec was selected. Tick at least two specs (including other characters' specs) to sync between them."] = "Sincronização limpa -- apenas uma especialização estava selecionada. Marque pelo menos duas especializações (incluindo especializações de outros personagens) para sincronizar entre elas."
L["Sync settings from:"] = "Sincronizar configurações de:"
L["Synced"] = "Sincronizado"
L["Synced with Raid Settings"] = "Sincronizado com as configurações de raide"
L["Synced with Simple Mode"] = "Sincronizado com o Modo Simples"
L["Syncing allows you to auto update all profiles whenever you change settings. This can be enabled per module."] = "A sincronização permite atualizar automaticamente todos os perfis sempre que você altera configurações. Isso pode ser ativado por módulo."
L["Syncing generic CDs/buffs across %d specs. Icon order is not synced -- each spec keeps its own arrangement."] = "Sincronizando recargas/buffs genéricos entre %d especializações. A ordem dos ícones não é sincronizada -- cada especialização mantém seu próprio arranjo."
L["Tabs"] = "Abas"
L["Talent gating is only available while playing this spec's class"] = "A restrição de talentos só está disponível enquanto joga com a classe desta especialização"
L["Target"] = "Alvo"
L["Target Unit"] = "Unidade alvo"
L["Targeting:"] = "Alvo:"
L["Targets"] = "Alvos"
L["The pasted string could not be read completely. Please paste it again."] = "A string colada não pôde ser lida completamente. Cole novamente."
L["The single stack threshold is off while Multiple Thresholds is on."] = "O limite de pilha única está desativado enquanto Múltiplos limites está ativado."
L["Thickness"] = "Espessura"
L["This Action Bar is also used as the Moonkin Form bar.\nChanging spells on a Druid for this bar will also change them on your Moonkin Form bar."] = "Esta barra de ação também é usada como a barra da Forma de Moonkin.\nAlterar feitiços de um Druida nesta barra também os altera na sua barra da Forma de Moonkin."
L["This bar will always be attached to your current target's nameplate"] = "Esta barra ficará sempre anexada à placa de nome do seu alvo atual"
L["This bar will always be attached to your focus target's nameplate"] = "Esta barra ficará sempre anexada à placa de nome do seu alvo de foco"
L["This can't change which spells the user tracks in Blizzard's CDM.\nIt's recommended to also share your Blizzard CDM layout for any spec you choose here."] = "Isso não altera quais feitiços o usuário rastreia no CDM da Blizzard.\nÉ recomendável também compartilhar seu layout do CDM da Blizzard para qualquer especialização escolhida aqui."
L["This cannot be undone. Export your own profile as a backup first."] = "Isso não pode ser desfeito. Exporte seu próprio perfil como backup primeiro."
L["This control recently changed direction: it now copies FROM the frame you choose. Confirming will copy all shared settings FROM %1$s TO %2$s."] = "Este controle mudou de direção recentemente: agora ele copia A PARTIR DO quadro que você escolher. Confirmar copiará todas as configurações compartilhadas DE %1$s PARA %2$s."
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "Esta exportação inclui configurações entre perfis que sobrescreverão as configurações do usuário que importar, incluindo Qualidade de Vida, Hovercast e outras que normalmente não deveriam ser compartilhadas com perfis padrão. ISSO NÃO É RECOMENDADO para compartilhamento público de perfis."
L["This is where you can control the settings of Unlock Mode.\n\nElements can be repositioned by dragging or arrow keys (+shift)\nAnchor, Height Match, or Width match any element.\nSnapping is based on closest element, but you can snap only to\n a specific element via right click or the settings icon."] = "Aqui você pode controlar as configurações do Modo de Desbloqueio.\n\nOs elementos podem ser reposicionados arrastando ou com as teclas de seta (+shift)\nAncore, corresponda a altura ou a largura de qualquer elemento.\nO encaixe é baseado no elemento mais próximo, mas você pode encaixar apenas em\n um elemento específico pelo clique direito ou pelo ícone de configurações."
L["This option requires Subtitle Text to include the Guild Name"] = "Esta opção requer que o texto do subtítulo inclua o nome da guilda"
L["This preset"] = "Esta predefinição"
L["This profile was made at %1$d%% UI scale; yours is %2$d%%. Change your UI scale to match the imported profile? This will show all profiles at this scale as UI Scale is not a per-profile setting, but can be changed at any time back to your original value."] = "Este perfil foi feito com %1$d%% de escala de interface; a sua é %2$d%%. Alterar sua escala de interface para corresponder ao perfil importado? Isso exibirá todos os perfis nesta escala, já que a Escala da Interface não é uma configuração por perfil, mas pode ser revertida ao seu valor original a qualquer momento."
L["This setting's active Apply to Bar (All Specs) value will be replaced."] = "O valor ativo de \"Aplicar à barra (todas as especializações)\" desta configuração será substituído."
L["This setting's active Apply to Bar value will be replaced."] = "O valor ativo de \"Aplicar à barra\" desta configuração será substituído."
L["This spell is already being used on %s"] = "Este feitiço já está sendo usado em %s"
L["This string is a FULL ACCOUNT export. It replaces your account-wide settings with the sender's, including Quality of Life, HoverCast bindings, Cooldown Manager spell setups, unlock anchors, UI scale, and profile keybinds -- not just a profile. Your other profiles are kept, but a profile with the same name is replaced."] = "Esta string é uma exportação de CONTA COMPLETA. Ela substitui suas configurações de toda a conta pelas do remetente, incluindo Qualidade de Vida, atalhos do HoverCast, configurações de feitiços do Gerenciador de Recarga, âncoras de desbloqueio, escala da interface e atalhos de perfil -- não apenas um perfil. Seus outros perfis são mantidos, mas um perfil com o mesmo nome é substituído."
L["This unit uses the Blizzard default frame -- there are no EllesmereUI settings to configure here."] = "Esta unidade usa o quadro padrão da Blizzard -- não há configurações do EllesmereUI para ajustar aqui."
L["This unit's frame is hidden -- there are no EllesmereUI settings to configure here."] = "O quadro desta unidade está oculto -- não há configurações do EllesmereUI para ajustar aqui."
L["This will replace YOUR Blizz UI Enhanced settings (the Window Skins and Tooltips, Menus & Popups tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "Isso substituirá SUAS configurações de Interface Blizz Aprimorada (as abas Aparência de Janelas e Dicas de Ferramenta, Menus e Pop-ups) pelas de quem compartilhou, em TODOS os seus perfis. Suas configurações atuais nessas duas abas não poderão ser recuperadas depois."
