-- == Unlock / Edit Mode =====================================================
L[" to be assigned to"] = " a ser atribuído a"
L["%s matched to %s. Unmatch in Unlock Mode to edit."] = "%s correspondido a %s. Desfaça a correspondência no Modo de Desbloqueio para editar."
