L["This overwrites this action menu's current settings. Its actions, name, and keybind are not changed."] = "Isso sobrescreve as configurações atuais deste menu de ações. Suas ações, nome e atalho não são alterados."
L["Copy every setting from another action menu to this one."] = "Copia todas as configurações de outro menu de ações para este."
L["Fixed Position"] = "Posição fixa"
