L["Editing Action Menu"] = "Editando menu de ações"
L["Action Menu Keybind"] = "Atalho do menu de ações"
L["Toggled Menu Select Action"] = "Ação de seleção do menu alternável"
L["Toggle Menu Open"] = "Manter menu aberto"
L["a Toggled Menu Select Action keybind"] = "um atalho de ação de seleção do menu alternável"
L["Uses the entry you are pointing at while a menu is kept open with Toggle Menu Open. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "Usa a entrada que você está apontando enquanto um menu é mantido aberto com Manter Menu Aberto. Uma tecla compartilhada por todos os menus, reivindicada apenas enquanto um menu está aberto -- um botão do mouse mantém seu uso normal no restante do tempo."
-- The Select Action picker localizes the COMPOSED intro + how-to-bind string
-- (one key); the two fragments above/below stay for pickers without an intro.
L["Uses the entry you are pointing at while a menu is kept open with Toggle Menu Open. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time.\n\nLeft-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "Usa a entrada que você está apontando enquanto um menu é mantido aberto com Manter Menu Aberto. Uma tecla compartilhada por todos os menus, reivindicada apenas enquanto um menu está aberto -- um botão do mouse mantém seu uso normal no restante do tempo.\n\nClique esquerdo para definir um atalho, depois pressione qualquer tecla\nou clique em qualquer botão do mouse para usá-lo.\nEsc cancela. Clique direito aqui para remover."
L["Grid Settings"] = "Configurações de grade"
L["Open At"] = "Abrir em"
