L["Arc Nest Shape"] = "Formato do aninhamento em arco"
L["Nest Width"] = "Largura do aninhamento"
L["How far along the arc a nest may spread its entries. Contained keeps it clear of the next nest either side, so two of them are never drawn on top of one another. Overflowing lets it use the whole of Max Nest Span."] = "Até onde ao longo do arco um aninhamento pode espalhar suas entradas. Contido o mantém afastado do próximo aninhamento de cada lado, para que dois nunca sejam desenhados um sobre o outro. Transbordar permite que ele use toda a Amplitude Máxima de Aninhamento."
L["Contained"] = "Contido"
L["Overflowing"] = "Transbordando"
L["Max Nest Span"] = "Amplitude máxima de aninhamento"
L["The widest angle a nest's entries may spread over. They stay on one ring for as long as they fit inside it; the rest go onto a second ring further out."] = "O ângulo mais amplo que as entradas de um aninhamento podem ocupar. Elas permanecem em um anel enquanto couberem nele; o restante vai para um segundo anel mais externo."
L["Grid Nest Style"] = "Estilo de aninhamento em grade"
L["Lane"] = "Faixa"
L["Halo"] = "Halo"
L["Show Cooldowns"] = "Mostrar recargas"
L["Dim Unusable Entries"] = "Escurecer entradas inutilizáveis"
L["Tint an entry that would do nothing right now: red when the target is out of range, blue when you are short of the resource, and gray when the game refuses it for any other reason. Spells and items only -- the game reports every toy as unusable, and a macro's usability depends on what its body resolves to."] = "Tinge uma entrada que não faria nada agora: vermelho quando o alvo está fora de alcance, azul quando falta recurso, e cinza quando o jogo a recusa por qualquer outro motivo. Apenas feitiços e itens -- o jogo reporta todo brinquedo como inutilizável, e a usabilidade de uma macro depende do que seu corpo resolve."
L["Selection Color"] = "Cor de seleção"
L["Show Action Text Label"] = "Mostrar rótulo de texto da ação"
L["Show the selected action's name next to the selected icon."] = "Mostra o nome da ação selecionada ao lado do ícone selecionado."
L["Custom Color"] = "Cor personalizada"
L["Accent Color"] = "Cor de destaque"
L["Hide Unusable Entries"] = "Ocultar entradas inutilizáveis"
L["Hide entries this character cannot use: another class's specializations and spells, and macros this character does not have. One shared menu then fits every character. The menu editor always shows every entry."] = "Oculta entradas que este personagem não pode usar: especializações e feitiços de outra classe, e macros que este personagem não possui. Assim, um único menu compartilhado serve para todos os personagens. O editor de menu sempre mostra todas as entradas."
L["Toggle World Markers"] = "Alternar marcadores de mundo"
L["Use a world marker entry again to pick that marker back up. Off places the marker again, at the new position.\nThis does not change the entry that clears all world markers, or the cycling entry."] = "Usar uma entrada de marcador de mundo novamente pega aquele marcador de volta. Desativado o coloca novamente, na nova posição.\nIsso não altera a entrada que limpa todos os marcadores de mundo, nem a entrada de ciclagem."
