L["Show Placed-Marker Pips"] = "Mostrar indicadores de marcador colocado"
L["Mark a world marker entry whose marker is on the ground with a small corner square, so you can see whether pressing it places or picks up."] = "Marca uma entrada de marcador de mundo cujo marcador está no chão com um pequeno quadrado no canto, para que você veja se pressioná-la coloca ou recolhe o marcador."
