L["Keep this menu open when you let go of its keybind.\nPoint at an entry and press the Select Action key to use it.\nPress the menu's own keybind again, or Escape, to close it."] = "Mantém este menu aberto quando você solta o atalho dele.\nAponte para uma entrada e pressione a tecla de Ação de Seleção para usá-la.\nPressione o atalho do próprio menu novamente, ou Esc, para fechá-lo."
L["Closes an open menu without using anything. Escape always does this as well. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "Fecha um menu aberto sem usar nada. Esc sempre faz isso também. Uma tecla compartilhada por todos os menus, reivindicada apenas enquanto um menu está aberto -- um botão do mouse mantém seu uso normal no restante do tempo."
