L["Sort Options"] = "Opções de ordenação"
L["Sort to Bottom"] = "Ordenar para o final"
L["Sorting normally packs your items into the first free slots, at the top of the grid. Turn this on to pack them into the last slots instead, so the empty slots end up at the top. The item order itself does not change. This affects the OneBag, MultiBag and bank views -- category views fill their own grid with no gaps, so there is nothing to move. MultiBag and the bank use Blizzard's own sorting, so while this is on it also flips Blizzard's cleanup direction; turning it back off restores the direction you had."] = "Ao ordenar, seus itens normalmente são compactados nos primeiros espaços livres, no topo da grade. Ative isso para compactá-los nos últimos espaços, deixando os espaços vazios no topo. A ordem dos itens em si não muda. Isso afeta as visões Bolsa Única, MultiBolsa e banco -- as visões de categoria preenchem sua própria grade sem lacunas, então não há nada para mover. MultiBolsa e o banco usam a ordenação nativa da Blizzard, então enquanto isso estiver ativo também inverte a direção de organização da Blizzard; desativar restaura a direção original."
L["Tab %1$d"] = "Aba %1$d"
L["The Armory"] = "O Arsenal"
L["This will physically scatter items to random positions in your bags. The changes persist even if you disable EllesmereUI Bags."] = "Isso espalhará fisicamente os itens para posições aleatórias nas suas bolsas. As alterações persistem mesmo se você desativar o EllesmereUI Bolsas."
L["Track and display gold amounts from all your characters on hover."] = "Rastreia e exibe a quantidade de ouro de todos os seus personagens ao passar o mouse."
L["Trade Goods"] = "Comércio"
L["Warband Bank"] = "Banco do Bando de Guerra"
L["Warband Gold"] = "Ouro do Bando de Guerra"
L["Weapons / Trinkets"] = "Armas / Berloques"
L["When enabled, left-click dragging the bag window will move it without needing to hold Shift."] = "Quando ativado, arrastar a janela da bolsa com o clique esquerdo a moverá sem precisar segurar Shift."
L["Which view bags (and the bank) open to by default. The bank has no MultiBag view, so MultiBag opens the bank to OneBank."] = "Determina com qual visão as bolsas (e o banco) abrem por padrão. O banco não tem visão MultiBolsa, então MultiBolsa abre o banco em Banco Único."
L["Withdraw"] = "Sacar"
L["Withdraw from Warbank"] = "Sacar do Banco do Bando de Guerra"

-- == Blizz UI Enhanced ========================================================
L["Accent bar on the active tab of reskinned windows."] = "Barra de destaque na aba ativa das janelas com aparência reestilizada."
L["Active In"] = "Ativo em"
L["Add diminishing-returns detail (adjusted rating, wasted rating, and current penalty bracket) to the Secondary and Tertiary stat tooltips."] = "Adiciona detalhes de retornos decrescentes (classificação ajustada, classificação desperdiçada e faixa de penalidade atual) às dicas de Estatísticas Secundárias e Terciárias."
L["AddOn List"] = "Lista de Addons"
L["Adds a strip down the left edge of a loot toast in the item's quality color. The flat skin drops Blizzard's quality ring around the icon, so this puts that rarity cue back."] = "Adiciona uma faixa na borda esquerda de um aviso de saque na cor de qualidade do item. A aparência plana remove o anel de qualidade da Blizzard ao redor do ícone, então isso traz de volta essa indicação de raridade."
L["Adds a Targeting line showing who the hovered player or NPC is targeting, in green when it's you."] = "Adiciona uma linha de Alvo mostrando quem o jogador ou NPC sob o cursor está mirando, em verde quando for você."
L["Adds the mount a player is riding to their tooltip, with a green check if you own it or a red X if you don't."] = "Adiciona a montaria que um jogador está montando à dica dele, com uma marca verde se você a possui ou um X vermelho se não possuir."
L["Also show the strip on gold toasts, in the header's gold color. Gold has no rarity to signal, so this is off by default."] = "Também mostra a faixa em avisos de ouro, na cor dourada do cabeçalho. Ouro não tem raridade para sinalizar, então isso vem desativado por padrão."
L["Alt"] = "Alt"
L["Anchor to Cursor"] = "Ancorar ao cursor"
L["Appends an item's max stack count on tooltip."] = "Adiciona a quantidade máxima de pilha de um item na dica."
L["Appends the spell or item ID to tooltips. The same setting as Global Settings > Developer."] = "Adiciona o ID do feitiço ou item às dicas. A mesma configuração de Configurações Globais > Desenvolvedor."
L["Applies EllesmereUI theme styling to the inspect sheet window."] = "Aplica o estilo do tema EllesmereUI à janela da ficha de inspeção."
L["Apply to All"] = "Aplicar a todos"
L["Auction House"] = "Casa de Leilões"
L["Background color for both Blizzard tooltips and EllesmereUI's own tooltips"] = "Cor de fundo tanto para as dicas da Blizzard quanto para as próprias dicas da EllesmereUI"
L["Background color for the Modern style."] = "Cor de fundo para o estilo Moderno."
L["Bar Fill Opacity"] = "Opacidade do preenchimento da barra"
L["Blizz Default"] = "Padrão Blizz"
L["BLIZZARD TOOLTIP"] = "DICA DA BLIZZARD"
L["Blizzard Window Skinning"] = "Reestilização de Janelas da Blizzard"
L["Blizzard Window Skins"] = "Aparências de Janelas da Blizzard"
L["Blizzard's options window chrome: frame, tabs, search, and category rail."] = "Moldura da janela de opções da Blizzard: quadro, abas, busca e barra de categorias."
L["Blizzard's windows match the EllesmereUI theme with a WoW 2.0 Dark Theme, from the Dungeon Journal to the Auction House and beyond."] = "As janelas da Blizzard combinam com o tema EllesmereUI usando um Tema Escuro WoW 2.0, do Diário de Masmorras à Casa de Leilões e além."
L["Brann's configuration window: role and trinket slots, abilities, and the ability list."] = "Janela de configuração do Brann: função e espaços de berloque, habilidades e a lista de habilidades."
