L["Shows the item level on each item in the character sheet gear flyout (the popup of same-slot bag items that appears when hovering an equipped slot), coloured by quality."] = "Mostra o nível de item em cada item no menu suspenso de equipamento da ficha de personagem (o pop-up de itens da bolsa do mesmo espaço que aparece ao passar o mouse sobre um espaço equipado), colorido pela qualidade."
L["Shows the item level on weapons and armor a vendor sells."] = "Mostra o nível de item em armas e armaduras vendidas por um vendedor."
L["Shows the items as a list instead of pages."] = "Mostra os itens como uma lista em vez de páginas."
L["Skin Third-Party Addons"] = "Aparência para addons de terceiros"
L["Socket Panel"] = "Painel de Encaixes"
L["Some addon skins could not apply live. A UI reload will fully apply them."] = "Algumas aparências de addons não puderam ser aplicadas ao vivo. Recarregar a interface as aplicará completamente."
