L["Style to apply to every window below."] = "Estilo a aplicar a todas as janelas abaixo."
L["Talents & Spellbook"] = "Talentos e Livro de Magias"
L["Tertiary Stats Settings"] = "Configurações de Estatísticas Terciárias"
L["The \"you have been invited to a group\" dialogs, with your role and Accept / Decline."] = "Os diálogos de \"você foi convidado para um grupo\", com sua função e Aceitar / Recusar."
L["The \"You received\" popups for loot, currency, and upgrades."] = "Os pop-ups de \"Você recebeu\" para saque, moeda e melhorias."
L["The achievement window: categories, rows, progress bars, and search."] = "A janela de conquistas: categorias, linhas, barras de progresso e busca."
L["The addon manager: list rows, checkboxes, and buttons."] = "O gerenciador de addons: linhas de lista, caixas de seleção e botões."
L["The auction house: browse, sell, and my auctions views."] = "A casa de leilões: visões de navegar, vender e meus leilões."
L["The class and profession trainer window: skill list, train button, and cost display."] = "A janela do instrutor de classe e profissão: lista de habilidades, botão de treinar e exibição de custo."
L["The customer crafting orders window: browse, order form, and my orders."] = "A janela de encomendas de criação de clientes: navegar, formulário de encomenda e minhas encomendas."
L["The gem socketing window with squared gem slots."] = "A janela de encaixe de gemas com espaços de gema quadrados."
L["The Guild & Communities window: roster, chat, and the community list."] = "A janela de Guilda e Comunidades: lista de membros, bate-papo e a lista de comunidades."
L["The housing dashboard window background, border, and title bar."] = "O fundo, a borda e a barra de título da janela do painel da moradia."
L["The item conversion window (catalyst and similar kiosks)."] = "A janela de conversão de itens (catalisador e similares)."
L["The item preview / transmog dressing room window."] = "A janela de pré-visualização de item / sala de provas de transmogrificação."
L["The item upgrade window: upgrade slot, track selector, cost, and the currency strip."] = "A janela de melhoria de item: espaço de melhoria, seletor de trilha, custo e a faixa de moedas."
L["The loot window: item rows with squared icons, kept item quality colors."] = "A janela de saque: linhas de item com ícones quadrados, mantendo as cores de qualidade dos itens."
L["The macro editor: tabs, icon grid, text well, and buttons."] = "O editor de macros: abas, grade de ícones, campo de texto e botões."
L["The mailbox: inbox rows, send mail, open mail, and attachment slots."] = "A caixa de correio: linhas da caixa de entrada, enviar correio, abrir correio e espaços de anexo."
L["The monthly calendar grid, event dialogs, and navigation arrows."] = "A grade do calendário mensal, diálogos de eventos e setas de navegação."
L["The need / greed / pass roll popups, with a squared icon and a flat roll timer."] = "Os pop-ups de rolagem de necessidade / cobiça / passar, com um ícone quadrado e um cronômetro de rolagem plano."
L["The NPC dialog window: greeting text, gossip and quest options, and goodbye button."] = "A janela de diálogo do NPC: texto de saudação, opções de conversa e missão, e botão de despedida."
L["The NPC quest window: quest detail, progress, and reward panels plus the multi-quest greeting list."] = "A janela de missão do NPC: detalhes, progresso e painéis de recompensa da missão, além da lista de saudação de múltiplas missões."
L["The pending-rolls window: encounter picker, roll timer, and the result rows."] = "A janela de rolagens pendentes: seletor de encontro, cronômetro de rolagem e as linhas de resultado."
L["The Player Spells window: talents, spec selection, and the spellbook."] = "A janela de Feitiços do Jogador: talentos, seleção de especialização e o livro de magias."
L["The profession crafting window: recipe list, schematic, specializations, and crafting orders."] = "A janela de criação de profissão: lista de receitas, esquema, especializações e encomendas de criação."
L["The professions overview book with squared icons and flat progress bars."] = "O livro de visão geral de profissões com ícones quadrados e barras de progresso planas."
L["The recipe preview window shown from a linked recipe or an inspected crafter."] = "A janela de pré-visualização de receita exibida a partir de uma receita vinculada ou de um artesão inspecionado."
L["The Social window frame, border, title bar, Battle.net bar, search boxes, filter dropdowns and buttons. List contents and the side tab icons stay untouched."] = "O quadro, a borda, a barra de título, a barra do Battle.net, as caixas de busca, os menus de filtro e os botões da janela Social. O conteúdo das listas e os ícones das abas laterais permanecem intocados."
L["The transmogrification window at the transmogrifier."] = "A janela de transmogrificação no transmogrificador."
L["The vendor window: item list, buyback, and bottom money bar."] = "A janela do vendedor: lista de itens, recompra e a barra de dinheiro inferior."
L["The world map window chrome and the quest log side panel."] = "A moldura da janela do mapa-múndi e o painel lateral do diário de missões."
L["Themed Blizzard frames: window skins, tooltips, menus, popups, Dragon Riding HUD."] = "Quadros da Blizzard com tema: aparências de janelas, dicas, menus, pop-ups, HUD de Pilotagem Aérea."
