-- == Presets / Profiles & Spec Overrides ======================================
L["+ Add New Spec Group"] = "+ Novo grupo de especialização"
L["A bright, minimalist layout with a clean aesthetic. Crafted for any role with clear information and a calm but focused feel."] = "Um layout claro e minimalista, com estética limpa. Criado para qualquer função, com informações claras e uma sensação calma, porém focada."
L["A clean minimal setup"] = "Um setup limpo e minimalista"
L["A clean, airy layout with a calm feel and clear information at a glance. Comfortable for long sessions in any content."] = "Um layout limpo e arejado, com uma sensação tranquila e informações claras à primeira vista. Confortável para sessões longas em qualquer conteúdo."
L["A dark, elegant healing setup built around raid frames and a clean display of information to help keep your team alive at a glance."] = "Um setup de cura escuro e elegante, construído em torno dos Quadros de Raide e de uma exibição limpa de informações para ajudar a manter sua equipe viva à primeira vista."
L["A luminous healing setup built around raid frames and crisp readability, keeping your team's health front and center at a glance."] = "Um setup de cura luminoso, construído em torno dos Quadros de Raide e de uma legibilidade nítida, mantendo a vida da sua equipe em destaque à primeira vista."
L["A shadowed, understated layout that keeps the screen quiet and the essentials close. Information appears exactly when you need it."] = "Um layout sombrio e discreto que mantém a tela silenciosa e o essencial por perto. As informações aparecem exatamente quando você precisa delas."
L["Another override group already provides the custom Buff Manager for your current spec."] = "Outro grupo de substituição já fornece o Gerenciador de Buffs personalizado para sua especialização atual."
L["Any setting you change now applies only to this group's specs."] = "Qualquer configuração alterada agora se aplica apenas às especializações deste grupo."
L["Any setting you change now applies only while this conditional is active."] = "Qualquer configuração alterada agora se aplica apenas enquanto este condicional estiver ativo."
L["Buff Manager changes on this page apply only to this override."] = "As alterações do Gerenciador de Buffs nesta página se aplicam apenas a esta substituição."
L["Captured overrides reference disabled modules (%s). Enable them and reload before promoting, or those settings would be lost."] = "As substituições capturadas fazem referência a módulos desativados (%s). Ative-os e recarregue a interface antes de promover, ou essas configurações serão perdidas."
L["Conditional"] = "Condicional"
L["Copy the string below and share it"] = "Copie a string abaixo e compartilhe-a"
L["Custom Unlock Mode"] = "Modo de Desbloqueio Personalizado"
L["Custom Unlock Modes"] = "Modos de Desbloqueio Personalizados"
L["Customize Unlock Mode"] = "Personalizar Modo de Desbloqueio"
L["Dark Theme"] = "Tema Escuro"
