L["Hide Power Bar if Resource"] = "Ocultar Barra de Poder se Houver Recurso"
L["Highlights the final damage tick. Requires a supported channeled spell."] = "Destaca o pulso de dano final. Requer um feitiço canalizado compatível."
L["Horizontal (Left)"] = "Horizontal (Esquerda)"
L["Horizontal (Right)"] = "Horizontal (Direita)"
L["Instance Only"] = "Apenas em Instâncias"
L["Keep the cast bar visible (sitting empty) when you are not casting, instead of hiding it."] = "Mantém a barra de lançamento visível (vazia) quando você não está lançando, em vez de ocultá-la."
L["Keep the GCD bar visible (sitting empty) when no global cooldown is running, instead of hiding it."] = "Mantém a barra de GCD visível (vazia) quando nenhuma recarga global está em andamento, em vez de ocultá-la."
L["Last Tick"] = "Último Pulso"
L["LATENCY"] = "LATÊNCIA"
L["Latency Overlay"] = "Sobreposição de Latência"
L["Makes partially filled Soul Shards and Essence darker than completed ones."] = "Deixa Fragmentos de Alma e Essência parcialmente preenchidos mais escuros que os completos."
L["Only available with the 'From' direction -- it highlights the pips at/above the threshold."] = "Disponível apenas com a direção 'De' -- destaca os segmentos no limite ou acima dele."
L["Only color at/above threshold"] = "Colorir Apenas no Limite ou Acima"
L["Only if Power Bar Hidden"] = "Somente se a Barra de Poder Estiver Oculta"
L["Only Instant Casts"] = "Apenas Lançamentos Instantâneos"
L["Only show the GCD bar for instant-cast abilities. While hard-casting or channeling a spell, the bar stays hidden (the cast bar already shows that progress)."] = "Mostra a barra de GCD apenas para habilidades de lançamento instantâneo. Durante um lançamento longo ou canalização, a barra permanece oculta (a barra de lançamento já mostra esse progresso)."
L["Only show the GCD bar while in a dungeon, raid, arena or battleground."] = "Mostra a barra de GCD apenas dentro de masmorras, raides, arenas ou campos de batalha."
L["Opacity of the bar fill; below 100 the world shows through the fill instead of the background."] = "Opacidade do preenchimento da barra; abaixo de 100 o mundo aparece através do preenchimento em vez do fundo."
L["Opacity of the resource fill; below 100 the world shows through the fill instead of the background."] = "Opacidade do preenchimento do recurso; abaixo de 100 o mundo aparece através do preenchimento em vez do fundo."
L["Out of Combat Opacity"] = "Opacidade Fora de Combate"
L["Pip Border"] = "Borda dos Segmentos"
L["Player Cast Bar"] = "Barra de Lançamento do Jogador"
L["Position by percent"] = "Posicionar por Porcentagem"
L["POSITIONING"] = "POSICIONAMENTO"
L["Power Background"] = "Fundo do Poder"
L["Power Bar Threshold"] = "Limite da Barra de Poder"
L["Power Value | Power %"] = "Valor de Poder | % de Poder"
L["Prot Warrior Ignore Pain Bar"] = "Barra de Ignorar Dor do Guerreiro de Proteção"
L["Recolor Text Instead Of Bar"] = "Recolorir Texto em Vez da Barra"
L["Replaces the class resource bar with an Ironfur tracker. Each Ironfur cast adds a hash line that slides from right to left as its buff decays. Duration is talent-aware (Ursoc's Endurance and Guardian of Elune)."] = "Substitui a barra de recurso de classe por um rastreador de Veloférreo. Cada lançamento de Veloférreo adiciona um traço que desliza da direita para a esquerda conforme o buff se esgota. A duração leva em conta talentos (Resistência de Ursoc e Guardião de Eluna)."
L["Requires Enhancement Shaman with Class Resource enabled."] = "Requer um Xamã de Fúria Elemental com Recurso de Classe ativado."
L["Resource Bars"] = "Barras de Recurso"
L["Reset Positions"] = "Redefinir Posições"
L["Resource Text"] = "Texto de Recurso"
L["Shift Elements if No Power"] = "Deslocar Elementos se Não Houver Poder"
L["Shift Elements if No Resource"] = "Deslocar Elementos se Não Houver Recurso"
L["Shift Offset"] = "Deslocamento"
L["Shifts any elements anchored to the class resource bar up or down to offset the missing class resource."] = "Desloca para cima ou para baixo quaisquer elementos ancorados à barra de recurso de classe, para compensar a ausência do recurso de classe."
L["Shifts any elements anchored to the power bar up or down to offset the missing power bar. Applies both when the Power Bar is disabled and for specs that have no power (for example, Beast Mastery and Marksmanship Hunters, whose Focus shows as the class resource bar)."] = "Desloca para cima ou para baixo quaisquer elementos ancorados à barra de poder, para compensar a ausência da barra de poder. Aplica-se tanto quando a Barra de Poder está desativada quanto para especializações sem poder (por exemplo, Caçadores de Domínio das Feras e Pontaria, cujo Foco aparece como a barra de recurso de classe)."
L["Show a small glowing spark that moves along the leading edge of the fill."] = "Mostra uma pequena centelha brilhante que se move ao longo da borda de avanço do preenchimento."
L["Show Fill Color When Idle"] = "Mostrar Cor de Preenchimento Quando Ocioso"
L["Show Focus as Power Bar (BM/MM)"] = "Mostrar Foco como Barra de Poder (BM/MM)"
L["Show Hash Line"] = "Mostrar Traço"
L["Show Health Bar"] = "Exibir Barra de Vida"
L["Show Latency Text"] = "Mostrar Texto de Latência"
L["Show Max Stacks"] = "Mostrar Pilhas Máximas"
L["Show Power Bar"] = "Exibir Barra de Poder"
L["Show rune count in center and remove recharge text/animation"] = "Mostra a contagem de runas no centro e remove o texto/animação de recarga"
L["Show Spell Icon"] = "Mostrar Ícone do Feitiço"
L["Show the bar full of its fill color while no global cooldown is running, instead of the background color."] = "Mostra a barra cheia com sua cor de preenchimento enquanto nenhuma recarga global está em andamento, em vez da cor de fundo."
L["Show the resource text only while the power bar is hidden - disabled, filtered off for this spec, a spec with no power, or hidden by \"Hide Power Bar if Resource\". Off = always show the text."] = "Exibe o texto do recurso apenas quando a barra de poder está oculta - desativada, filtrada para esta especialização, uma especialização sem poder, ou oculta por \"Ocultar Barra de Poder se Houver Recurso\". Desligado = sempre exibe o texto."
L["Show Timer"] = "Exibir Cronômetro"
L["Show Total Duration"] = "Mostrar Duração Total"
L["Shows a bar that fills over the global cooldown."] = "Mostra uma barra que se preenche ao longo da recarga global."
L["Shows a colored overlay at the end of the cast bar representing your network latency for each spell. Helps you time spell queuing."] = "Mostra uma sobreposição colorida no final da barra de lançamento representando sua latência de rede para cada feitiço. Ajuda a cronometrar o enfileiramento de feitiços."
L["Shows elapsed / total duration (e.g. 0.4 / 2.0) instead of counting down from the total."] = "Mostra a duração decorrida / total (ex.: 0.4 / 2.0) em vez de contar regressivamente a partir do total."
L["Shows tick marks on channeled spells. Only supported spells are shown, request missing spells on Discord."] = "Mostra marcadores de pulso em feitiços canalizados. Apenas feitiços com suporte são exibidos; peça feitiços ausentes no Discord."
L["Simple Runes"] = "Runas Simples"
L["Single"] = "Único"
