L["This option applies to pip-type resources only."] = "Esta opção se aplica apenas a recursos do tipo segmento."
L["This option can't be used while Expand Power Bar if No Resource is enabled."] = "Esta opção não pode ser usada enquanto Expandir Barra de Poder se Não Houver Recurso estiver ativado."
