L["This option can't be used while you have the Power Bar Height Matched in the Unlock Mode."] = "Esta opção não pode ser usada enquanto a Altura da Barra de Poder estiver Correspondida no Modo de Desbloqueio."
L["This option requires a Border Size above 0."] = "Esta opção requer um Tamanho de Borda acima de 0."
