L["This option requires a Power Text format other than None"] = "Esta opção requer um formato de Texto de Poder diferente de Nenhum"
L["This option requires Threshold Settings to be disabled"] = "Esta opção requer que as Configurações de Limite estejam desativadas"
L["Threshold %"] = "Limite %"
L["Threshold & Hash Lines"] = "Limite e Traços"
