L["Custom shapes always use Shape Glow -- change your bar shape to None or Cropped to pick a different glow"] = "Formatos personalizados sempre usam o Brilho de Formato -- mude o formato da sua barra para Nenhum ou Recortado para escolher um brilho diferente"
L["Desaturate on Cooldown"] = "Dessaturar em Recarga"
