L["Dims action button icons to this opacity while on cooldown (100 = off), using the same detection as Desaturate on Cooldown."] = "Escurece os ícones dos botões de ação até esta opacidade enquanto estão em recarga (100 = desativado), usando a mesma detecção de Dessaturar em Recarga."
