L["Hide the charge number on action buttons when it reaches 0, instead of showing a 0. The number returns as soon as a charge or item comes back."] = "Oculta o número de cargas nos botões de ação quando chega a 0, em vez de mostrar um 0. O número volta assim que uma carga ou item retorna."
