L["Icon Outset"] = "Deslocamento Externo do Ícone"
L["Keep Action Bar 1 on its current page when you shapeshift, stealth, or change stance, instead of swapping to that form's bar.\n\nKeybinds follow what the bar shows, so the key always casts the icon you see. Press-and-hold repeat casting is turned off on Action Bar 1 while this is enabled."] = "Mantém a Barra de Ação 1 na página atual quando você muda de forma, entra em furtividade ou muda de postura, em vez de trocar para a barra daquela forma.\n\nOs atalhos seguem o que a barra exibe, então a tecla sempre lança o ícone que você vê. O lançamento repetido ao pressionar e segurar é desativado na Barra de Ação 1 enquanto isso estiver ativado."
L["Keep Action Bar 1 on its current page while skyriding, instead of swapping to the skyriding bar.\n\nYour skyriding abilities live on that bar, so put them on another bar before enabling this. Press-and-hold repeat casting is turned off on Action Bar 1 while this is enabled."] = "Mantém a Barra de Ação 1 na página atual durante a Pilotagem Aérea, em vez de trocar para a barra de Pilotagem Aérea.\n\nSuas habilidades de Pilotagem Aérea ficam nessa barra, então coloque-as em outra barra antes de ativar isso. O lançamento repetido ao pressionar e segurar é desativado na Barra de Ação 1 enquanto isso estiver ativado."
L["Keybind Text Offsets"] = "Deslocamentos do Texto de Atalho"
L["Keybind Text Size"] = "Tamanho do Texto de Atalho"
