L["Feathered"] = "Emplumado"
L["Flash the enemy's cast bar and show \"Interrupted\" for a moment when their cast is interrupted. Use the swatch to change the flash colour."] = "Faz a barra de lançamento do inimigo piscar e mostra \"Interrompido\" por um instante quando o lançamento é interrompido. Use a amostra de cor para alterar a cor do flash."
