L["Show a glow on the cast bar when the enemy is casting a spell Blizzard marks as important."] = "Mostra um brilho na barra de lançamento quando o inimigo está lançando um feitiço que a Blizzard marca como importante."
L["Show a shield icon on the cast bar when an enemy's cast cannot be interrupted."] = "Mostra um ícone de escudo na barra de lançamento quando o lançamento de um inimigo não pode ser interrompido."
