L["Show successful interrupt lockouts in the crowd-control icon slot.\n\nDue to addon restrictions, the duration shown is a generic 4 seconds for all classes, so it is not 100% accurate."] = "Mostra interrupções bem-sucedidas no slot de ícone de controle de grupo.\n\nDevido a restrições do addon, a duração exibida é um valor genérico de 4 segundos para todas as classes, portanto não é 100% precisa."
L["Show/Hide Hitbox Overlay"] = "Mostrar/Ocultar Sobreposição da Área de Clique"
