L["Shows a special color for nameplates that another tank in your raid has aggro on."] = "Mostra uma cor especial para placas de nome nas quais outro tanque da sua raide tem ameaça."
L["Shows a special color for non caster/mini-boss enemies when you do not have aggro on them."] = "Mostra uma cor especial para inimigos que não são conjuradores/minichefes quando você não tem ameaça sobre eles."
L["Shows a special color for non caster/mini-boss enemies when you have aggro on them."] = "Mostra uma cor especial para inimigos que não são conjuradores/minichefes quando você tem ameaça sobre eles."
L["Shows the approximate distance to your current target on its nameplate as a range bracket, e.g. 15+ when the target is 15-20 yards away."] = "Mostra a distância aproximada até o seu alvo atual na placa de nome dele como uma faixa de alcance, ex.: 15+ quando o alvo está a 15-20 jardas de distância."
L["Shows the target marker directly before the enemy name text. Uses its own size and does not use the Core Positions raid marker slot."] = "Mostra o marcador de alvo diretamente antes do texto do nome do inimigo. Usa seu próprio tamanho e não usa o slot de marcador de raide das Posições Principais."
L["Shows where your interrupt will be ready during an enemy cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "Mostra onde sua interrupção estará pronta durante o lançamento de um inimigo. \"Marca\" indica o ponto exato na barra de lançamento; \"Marca + Barra\" também colore a janela durante a qual sua interrupção estará disponível."
