L["Keep keybind text identical when your action bar swaps -- rogue stealth, druid forms, skyriding. Also covers conditional macros like \"/cast [bonusbar:1] Backstab; Shadow Dance\", where the key would otherwise jump to whichever branch is live.\n\nThe key then only changes when you actually move the ability or rebind it.\n\nOn by default. Applies to every CDM bar at once."] = "Mantém o texto do atalho idêntico quando sua barra de ação troca -- furtividade de ladino, formas de druida, pilotagem aérea. Também cobre macros condicionais como \"/cast [bonusbar:1] Ataque Pelas Costas; Dança das Sombras\", onde a tecla mudaria para o que quer que esteja ativo no momento.\n\nA tecla só muda quando você realmente move a habilidade ou a rebind.\n\nAtivado por padrão. Aplica-se a todas as barras do CDM de uma vez."
