L["Vertical Gradient"] = "Gradiente Vertical"
L["When you press an ability's keybind, show the action button's \"pushed down\" look on its icon on this bar -- even while the ability is on cooldown."] = "Quando você pressiona o atalho de uma habilidade, mostra a aparência \"pressionado\" do botão de ação no ícone desta barra -- mesmo enquanto a habilidade está em recarga."
L["When your bags have none of one potion type, its icon swaps to track the other type."] = "Quando suas mochilas não têm nenhuma poção de um tipo, o ícone troca para rastrear o outro tipo."
L["Wrong Bar Type"] = "Tipo de Barra Incorreto"
L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n1. Disable EllesmereUI Cooldown Manager (button below).\n2. Open Edit Mode from the Game Menu.\n3. Select each Cooldown Manager viewer and set Visibility to Always.\n4. On Tracked Buffs and Tracked Bars, tick Hide When Inactive.\n5. Save the layout and leave Edit Mode.\n6. Re-enable EllesmereUI Cooldown Manager."] = "A EllesmereUI não conseguiu salvar esta alteração no seu layout do Modo de Edição, então ela precisa ser feita manualmente. O Gerenciador de Recarga precisa estar desativado enquanto você faz isso, pois ele oculta os visualizadores de recarga da Blizzard e um visualizador oculto não pode ser selecionado no Modo de Edição.\n\n1. Desative o Gerenciador de Recarga da EllesmereUI (botão abaixo).\n2. Abra o Modo de Edição pelo Menu do Jogo.\n3. Selecione cada visualizador do Gerenciador de Recarga e defina a Visibilidade como Sempre.\n4. Em Buffs Rastreados e Barras Rastreadas, marque Ocultar Quando Inativo.\n5. Salve o layout e saia do Modo de Edição.\n6. Reative o Gerenciador de Recarga da EllesmereUI."
L["This will keep appearing each login until the layout is correct."] = "Isso continuará aparecendo a cada login até que o layout esteja correto."
