L["Show Duration (Inside Cog)"] = "Mostrar Duração (Dentro da Engrenagem)"
L["Show every buff that has a duration (hides permanent buffs). While this is on, checked filters below are hidden instead of added."] = "Mostra todo buff que tem duração (oculta buffs permanentes). Enquanto isso estiver ativado, os filtros marcados abaixo ficam ocultos em vez de adicionados."
L["Show every buff. While this is on, checked filters below are hidden from the frame instead of added."] = "Mostra todo buff. Enquanto isso estiver ativado, os filtros marcados abaixo ficam ocultos do quadro em vez de adicionados."
L["Show every debuff. While this is on, checked filters below are hidden from the frame instead of added."] = "Mostra todo debuff. Enquanto isso estiver ativado, os filtros marcados abaixo ficam ocultos do quadro em vez de adicionados."
L["Show heal absorb preview"] = "Mostrar pré-visualização da absorção de cura"
L["Show Highlight Border"] = "Mostrar Borda de Destaque"
L["Show Icon on Right"] = "Mostrar Ícone à Direita"
L["Show in Instances"] = "Mostrar em Instâncias"
L["Show Kick Ready Mid-Cast Bar"] = "Mostrar Barra de Interrupção Pronta Durante o Lançamento"
