L["Value | %"] = "Valor | %"
L["Vertical Spacing"] = "Espaçamento Vertical"
L["Weapon Enchants"] = "Encantamentos de Arma"
L["When your interrupt is on cooldown now but will be ready before the enemy cast finishes, color the part of the cast bar during which your interrupt will be available. The color clears the instant your interrupt comes off cooldown."] = "Quando sua interrupção está em recarga mas ficará pronta antes do lançamento inimigo terminar, colore a parte da barra de lançamento durante a qual sua interrupção estará disponível. A cor desaparece no instante em que sua interrupção sai da recarga."
L["Due to Blizzard API restrictions, Blizzard's native target-of-target can't be hidden in combat and will show the whole time you are in combat. Recommended: match the Target frame's source -- both Blizzard Default, or both EllesmereUI."] = "Devido a restrições da API da Blizzard, o quadro nativo de Alvo do Alvo da Blizzard não pode ser ocultado em combate e ficará visível durante todo o combate. Recomendado: usar a mesma fonte do quadro de Alvo -- ambos Padrão da Blizzard, ou ambos EllesmereUI."
L["Due to Blizzard API restrictions, Blizzard's native focus-target can't be hidden in combat and will show the whole time you are in combat. Recommended: match the Focus frame's source -- both Blizzard Default, or both EllesmereUI."] = "Devido a restrições da API da Blizzard, o quadro nativo de Alvo do Foco da Blizzard não pode ser ocultado em combate e ficará visível durante todo o combate. Recomendado: usar a mesma fonte do quadro de Foco -- ambos Padrão da Blizzard, ou ambos EllesmereUI."
L["\"Blizzard Default\" is only available when the Target frame's source is set to Blizzard Default -- the target-of-target then comes from Blizzard's target frame."] = "\"Padrão da Blizzard\" só está disponível quando a fonte do quadro de Alvo está definida como Padrão da Blizzard -- o Alvo do Alvo então vem do quadro de alvo da Blizzard."
L["\"Blizzard Default\" is only available when the Focus frame's source is set to Blizzard Default -- the focus-target then comes from Blizzard's focus frame."] = "\"Padrão da Blizzard\" só está disponível quando a fonte do quadro de Foco está definida como Padrão da Blizzard -- o Alvo do Foco então vem do quadro de foco da Blizzard."
L["the Frame Source to be EllesmereUI"] = "que a Fonte do Quadro seja EllesmereUI, para que ela"
