L["When you join a Group Finder group for a dungeon that has a teleport, shows a small movable popup with the dungeon name and a one-click teleport button. It hides when you enter the dungeon, leave the group, or enter combat."] = "Quando você entra em um grupo do Buscador de Grupo para uma masmorra que tem teletransporte, exibe um pequeno pop-up móvel com o nome da masmorra e um botão de teletransporte de um clique. Fica oculto quando você entra na masmorra, sai do grupo ou entra em combate."

