-- Mythic+ threshold descriptions
L["Reminder threshold while you are in a dungeon before a Mythic+ key starts (Mythic 0 / keystone lobby). Set it high enough that you top up buffs and food before pulling, so you begin the key with enough duration to last it.\n0 = only when fully expired.\nIgnored once the key is active or you are in combat (then only when the buff is fully gone)."] = "Limite de aviso enquanto você está em uma masmorra antes do início de uma chave Mythic+ (Mítico 0 / lobby da pedra-chave). Defina alto o suficiente para renovar buffs e comida antes do primeiro pull, para começar a chave com duração suficiente até o fim.\n0 = apenas quando totalmente expirado.\nIgnorado assim que a chave estiver ativa ou você estiver em combate (aí só quando o buff acabar por completo)."
L["Show reminders when remaining buff time is below this many minutes.\n0 = only when fully expired.\nIgnored in combat and during Mythic+ keys (then only when the buff is gone)."] = "Exibe lembretes quando o tempo restante do buff está abaixo desta quantidade de minutos.\n0 = apenas quando totalmente expirado.\nIgnorado em combate e durante chaves Mythic+ (aí só quando o buff tiver acabado)."

