L["Background opacity for Dark Mode bars. Applies to Unit Frames and Raid Frames only (Resource Bars ignore it)."] = "Opacidade de fundo para barras do Modo Escuro. Aplica-se apenas a Quadros de Unidade e Quadros de Raide (Barras de Recurso ignoram isso)."
L["Bags Icons"] = "Ícones de Bolsas"
