L["Enables sharpening to improve image clarity. Especially noticeable at lower render scales."] = "Ativa nitidez para melhorar a clareza da imagem. Especialmente perceptível em escalas de renderização mais baixas."
L["FPS & Graphics Optimization"] = "Otimização de FPS e Gráficos"
L["Fill opacity for Dark Mode bars. Applies to Unit Frames and Raid Frames only (Resource Bars ignore it)."] = "Opacidade de preenchimento para barras do Modo Escuro. Aplica-se apenas a Quadros de Unidade e Quadros de Raide (Barras de Recurso ignoram isso)."
L["Forces a crisp outline on icon text (stack counts, durations, keybinds). Uncheck a module to make its icon text follow the Outline Mode setting above instead."] = "Força um contorno nítido no texto dos ícones (contagem de pilhas, durações, atalhos). Desmarque um módulo para que o texto do ícone siga a configuração Modo de Contorno acima."
L["General options for all EllesmereUI addons."] = "Opções gerais para todos os addons da EllesmereUI."
L["Global Font"] = "Fonte Global"
L["Hide Pause Menu Button"] = "Ocultar Botão do Menu de Pausa"
L["Hide Unlock Mode Menu Button"] = "Ocultar Botão do Menu do Modo de Desbloqueio"
L["Hides the EllesmereUI button from the game's Escape/pause menu."] = "Oculta o botão da EllesmereUI do menu Esc/pausa do jogo."
L["Hides the Unlock Mode button from the game's Escape/pause menu. You can still toggle Unlock Mode from the EUI options panel."] = "Oculta o botão do Modo de Desbloqueio do menu Esc/pausa do jogo. Você ainda pode alternar o Modo de Desbloqueio pelo painel de opções da EUI."
L["Hides the sync icons on the sidebar module list."] = "Oculta os ícones de sincronização na lista de módulos da barra lateral."
L["Import, export, and switch EllesmereUI profiles and presets."] = "Importe, exporte e alterne entre perfis e predefinições da EllesmereUI."
L["Increase Game Image Quality"] = "Aumentar Qualidade de Imagem do Jogo"
L["Keybinds respond on key down instead of key up. This helps make your abilities feel more responsive."] = "Os atalhos respondem ao pressionar a tecla em vez de soltá-la. Isso ajuda a fazer suas habilidades parecerem mais responsivas."
L["Lag Tolerance"] = "Tolerância de Lag"
L["Logout Required"] = "Logout Necessário"
L["Max Camera Distance"] = "Distância Máxima da Câmera"
L["Name Font"] = "Fonte de Nome"
L["On (default): one profile's palette is shared across every profile (chosen via Pull Colors From). Off: each profile keeps its own custom colors (Power, Class Resource, Class, Resource)."] = "Ativado (padrão): a paleta de um perfil é compartilhada entre todos os perfis (escolhido via Copiar Cores De). Desativado: cada perfil mantém suas próprias cores personalizadas (Poder, Recurso de Classe, Classe, Recurso)."
L["Only Hide Fully Synced"] = "Ocultar Apenas Totalmente Sincronizados"
L["Outline Icon Text"] = "Contornar Texto do Ícone"
L["Power Color Darken"] = "Escurecimento de Cor de Poder"
L["Prevent Swiftmend Icon Dim"] = "Evitar Escurecimento do Ícone de Recomposição Rápida"
L["Prevents Blizzard from dimming Swiftmend on action bars and CDM based on Efflorescence state."] = "Impede que a Blizzard escureça Recomposição Rápida nas barras de ação e no CDM com base no estado de Eflorescência."
L["Pull Colors From"] = "Copiar Cores De"
L["Raid Frames Icons"] = "Ícones de Quadros de Raide"
L["Reset ALL Settings"] = "Redefinir TODAS as Configurações"
L["Resource Color Darken"] = "Escurecimento de Cor de Recurso"
L["Set UI Scale to 0.5333"] = "Definir Escala da Interface para 0.5333"
L["Sets the UI scale to the exact pixel-perfect value used by other addons. EllesmereUI does not require this to be pixel perfect."] = "Define a escala da interface para o valor exato de pixel perfeito usado por outros addons. A EllesmereUI não exige que seja pixel perfeito."
L["Sets the accent color used across all EllesmereUI elements (tabs, glows, highlights, borders). Defaults to your theme color."] = "Define a cor de destaque usada em todos os elementos da EllesmereUI (abas, brilhos, realces, bordas). O padrão é a cor do seu tema."
L["Sets the font for the names that float above players, NPCs and enemies in the world.\n\nSeparate from Global Font - changing this does not affect the rest of the UI, and Global Font does not affect it.\n\nBlizzard Default leaves the name text completely untouched.\n\n|cffff4d4dRequires a re-log or restart of WoW to take effect.|r"] = "Define a fonte para os nomes que flutuam acima de jogadores, NPCs e inimigos no mundo.\n\nSepara da Fonte Global - alterar isso não afeta o resto da interface, e a Fonte Global não a afeta.\n\nPadrão da Blizzard deixa o texto do nome completamente intocado.\n\n|cffff4d4dRequer relogar ou reiniciar o WoW para ter efeito.|r"
L["Sets the scale of the entire game UI. Lower values make everything smaller, higher values make everything larger."] = "Define a escala de toda a interface do jogo. Valores menores deixam tudo menor; valores maiores deixam tudo maior."
L["Show Combat Damage Text"] = "Exibir Texto de Dano de Combate"
L["Show Combat Healing Text"] = "Exibir Texto de Cura de Combate"
L["Show Minimap Button"] = "Exibir Botão do Minimapa"
L["Show Periodic Damage"] = "Exibir Dano Periódico"
L["Show Pet Melee Damage"] = "Exibir Dano Corpo a Corpo do Ajudante"
L["Show Pet Spell Damage"] = "Exibir Dano de Feitiço do Ajudante"
L["Show one-time video guide badges next to new or complex features. Each badge disappears forever once clicked."] = "Exibe emblemas de guia em vídeo únicos ao lado de recursos novos ou complexos. Cada emblema desaparece para sempre assim que é clicado."
L["Slug outline renders higher quality outlines compared to the base WoW outline mode but may make outline effects appear slightly thicker."] = "O contorno Slug renderiza contornos de qualidade superior em comparação ao modo de contorno padrão do WoW, mas pode fazer os efeitos de contorno parecerem um pouco mais grossos."
L["Sync Icon Options"] = "Opções de Ícone de Sincronização"
L["System Default"] = "Padrão do Sistema"
L["The background colour behind Dark Mode bars (Unit Frames, Raid Frames, Resource Bars)."] = "A cor de fundo atrás das barras do Modo Escuro (Quadros de Unidade, Quadros de Raide, Barras de Recurso)."
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "O idioma de exibição do painel de opções da EllesmereUI. Automático segue o cliente do jogo. Textos não traduzidos usam o inglês como padrão."
L["The flat fill colour bars use when Dark Mode is enabled (Unit Frames, Raid Frames, Resource Bars)."] = "A cor de preenchimento sólida que as barras usam quando o Modo Escuro está ativado (Quadros de Unidade, Quadros de Raide, Barras de Recurso)."
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "Esta é a Janela de Fila de Feitiços; ela ajuda a garantir que você não enfileire feitiços demais de uma vez, o que deixa o jogo parecendo travado. As configurações recomendadas geralmente são um mínimo de 200 + seu ping local. Se você não tem certeza do que esta configuração faz exatamente, deixe em 400."
L["Toggle EllesmereUI's optional buttons: the Escape menu buttons and the minimap button."] = "Alterna os botões opcionais da EllesmereUI: os botões do menu Esc e o botão do minimapa."
L["Turns Dark Mode on or off for Unit Frames and Raid Frames at once."] = "Ativa ou desativa o Modo Escuro para Quadros de Unidade e Quadros de Raide de uma vez."
L["Turns Dark Mode on or off for the class resource bar."] = "Ativa ou desativa o Modo Escuro para a barra de recurso de classe."
L["UI Accent Color"] = "Cor de Destaque da Interface"
L["UI Scale"] = "Escala da Interface"
L["UI Scale Changed"] = "Escala da Interface Alterada"
L["UI Scale Options"] = "Opções de Escala da Interface"
L["Unlock Mode Layout"] = "Layout do Modo de Desbloqueio"
L["WARNING: This feature requires you to re-log or restart WoW to take effect."] = "AVISO: Este recurso requer que você relogue ou reinicie o WoW para ter efeito."
L["Window & Tooltip Skins"] = "Aparências de Janelas e Dicas de Ferramenta"

