-- == Presets / Profiles & Spec Overrides (per-addon export/import descriptions) =
L["Modern action bars built for performance and clarity."] = "Barras de ação modernas, construídas para desempenho e clareza."
L["Clean, lightweight nameplates with endless customization."] = "Placas de nome limpas e leves, com personalização infinita."
L["Simple unit frames with a modern visual style."] = "Quadros de unidade simples, com um estilo visual moderno."
L["A CDM replacement focused on performance, customizations and alerts."] = "Uma substituta do CDM focada em desempenho, personalizações e alertas."
L["Custom Resource Bars with thresholds, hash lines and more."] = "Barras de Recurso personalizadas com limites, linhas de marcação e muito mais."
L["Incredibly light performance, modern raid frames with endless flexibility."] = "Desempenho incrivelmente leve, quadros de raide modernos com flexibilidade infinita."
L["Simple raid buff, auras, consumables and talent reminders."] = "Lembretes simples de buffs de raide, auras, consumíveis e talentos."
L["Lightweight quality of life tools and enhancements."] = "Ferramentas e melhorias leves de qualidade de vida."
L["Skyriding HUD with speed, vigor and second wind tracking."] = "HUD de Pilotagem Aérea com rastreamento de velocidade, vigor e fôlego extra."
L["Clean and beautiful visual refreshes for Blizzard UI elements."] = "Renovações visuais limpas e bonitas para elementos da interface da Blizzard."
L["A modern friends list with built-in organization tools."] = "Uma lista de amigos moderna com ferramentas de organização integradas."
L["A new age minimap with clean styling and square layout options."] = "Um minimapa de nova geração com estilo limpo e opções de layout quadrado."
L["Lightweight damage meters with simple but powerful customization."] = "Medidores de dano leves, com personalização simples mas poderosa."
L["Modern chat enhancements with useful utilities."] = "Melhorias modernas de chat com utilitários úteis."
L["A beautiful visual refresh of Blizzard Bags with intuitive organization."] = "Uma bela renovação visual das Mochilas da Blizzard, com organização intuitiva."
L["Hold a key to open a menu of actions; point or scroll to choose, release to fire."] = "Segure uma tecla para abrir um menu de ações; aponte ou role para escolher, solte para disparar."
