L["The delve difficulty window: tier dropdown, reward list and Enter button. The Map Properties row is left stock -- it is a Blizzard widget display and is not safe to restyle."] = "A janela de dificuldade das profundezas: menu suspenso de nível, lista de recompensas e botão de Entrar. A linha de Propriedades do Mapa é deixada no padrão -- é uma exibição de widget da Blizzard e não é seguro reestilizá-la."
L["The panel the minimap Group Finder eye shows on hover: queue titles, role icons and counts, and time in queue."] = "O painel que o olho de Busca de Grupo do minimapa mostra ao passar o mouse: títulos da fila, ícones e contagens de função, e tempo na fila."
L["The player-to-player trade window: frame, both item columns, the enchant slots, money rows and buttons. Item icons are squared and carry a rarity border. Both portraits are removed, as on every other window."] = "A janela de comércio entre jogadores: quadro, ambas as colunas de itens, os espaços de encantamento, linhas de dinheiro e botões. Os ícones de item ficam quadrados e ganham uma borda de raridade. Ambos os retratos são removidos, como em toda outra janela."
L["The ready check prompt with its Yes / No buttons, plus the initiator's response list."] = "A mensagem de confirmação de pronto com seus botões Sim / Não, além da lista de respostas do iniciador."
L["These specs hold override values that no group's editing mode can reach anymore (left behind by membership changes). They still apply. Remove one to return that spec to the shared default."] = "Essas especializações mantêm valores de substituição que o modo de edição de nenhum grupo mais consegue alcançar (deixados para trás por mudanças de composição). Elas continuam se aplicando. Remova uma para retornar essa especialização ao padrão compartilhado."
L["This bar has an Additional Bar Offset (X %1$s, Y %2$s) set in its options. Unlock mode shows the base position; the offset re-applies when you exit."] = "Esta barra tem um Deslocamento Adicional da Barra (X %1$s, Y %2$s) definido em suas opções. O modo de desbloqueio mostra a posição base; o deslocamento volta a ser aplicado quando você sai."
L["This group's custom Debuff Manager can only be activated or edited while playing one of its specs."] = "O Gerenciador de Debuffs personalizado deste grupo só pode ser ativado ou editado enquanto você joga uma de suas especializações."
L["This will create a fully unique Debuff Manager for this conditional group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect it."] = "Isso criará um Gerenciador de Debuffs totalmente exclusivo para este grupo condicional. Suas configurações atuais do Gerenciador de Debuffs são copiadas como ponto de partida, e alterações feitas no seu Gerenciador de Debuffs padrão não afetarão mais isso."
L["This will create a fully unique Debuff Manager for this override group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect these specs."] = "Isso criará um Gerenciador de Debuffs totalmente exclusivo para este grupo de substituição. Suas configurações atuais do Gerenciador de Debuffs são copiadas como ponto de partida, e alterações feitas no seu Gerenciador de Debuffs padrão não afetarão mais essas especializações."
